-- 459_hidden_curated_3.sql — #459 Cleveland story batch, part 4: 21 HIDDEN storyless OSM pins from the 122-pin gate-drops union
-- brought back with a story (drafted 2026-11-05). Same shape and rules as 459_hidden_curated.sql: exact stored name at the stored
-- coordinate, read from a fresh stored places:v34 read of all 51 stored tiles (48 box + ring) on 2026-11-05; every row passes #542
-- by pin id (the containing tile stores it), none is served in a live serve of its tiles the same day (curatedIndexRows 2,493),
-- and none has a same-name pin within 2 km or a same-name line in parts 1–3h. Verdicts: 459_gate_drops_cleveland.tsv.
-- Sources: Cleveland Historical (Cultural Gardens 115/130/133, The Thinker 575), the Encyclopedia of Cleveland History (Moses
-- Cleaveland Statue; Louis Kossuth's Visit), NPS (Public Square — Tom L. Johnson), teachingcleveland.org (the 1944 East Ohio Gas
-- explosion victims' monument, Highland Park Cemetery) and Wikipedia; every number and capitalised name checked against its
-- source text (checker re-proven on 1947 / "Johnsen"). Distinct things beside served pins, each its own subject: Free Stamp in
-- the served Willard Park (32 m), Mindszenty's monument beside the served Hungarian Freedom Fighter Statue (7 m).
-- Batch file — run in the Mac session after the seed commit and after 459_hidden_curated.sql and 459_hidden_curated_2.sql, then
-- curated_category_backfill(true). Expect 21 returned names, first "Buckland Museum of Witchcraft and Magick"; "Success. No rows returned"
-- means the guard skipped (already run — FROM RIVERSIDE (7)).
with v(name, lat, lng, description, source_url, note) as (values
  ($t$Buckland Museum of Witchcraft and Magick$t$, 41.4381207::double precision, -81.6997569::double precision, $t$Raymond Buckland began this collection in 1968 as the first museum of witchcraft and magick in the United States, starting in his own basement; after years in storage its artifacts are now displayed here in Cleveland.$t$, $t$https://en.wikipedia.org/wiki/Raymond_Buckland$t$, $t$#459 hidden-pin row: osm_node7011743170, stored in 829_-1634; containing tile 829_-1634 stores it (#542)$t$),
  ($t$Kossuth Lajos Statue$t$, 41.5038158::double precision, -81.6112961::double precision, $t$Ahead of the 50th anniversary of Kossuth's 1852 visit, a Kossuth Statue Committee had Andras Toth reproduce his memorial from Nagyszalonta, Hungary, and set it on earth sent from each county in Hungary; the statue was presented to the city in 1902.$t$, $t$https://ech-dev.cwru.edu/cgi/article.pl?id=LKV$t$, $t$#459 hidden-pin row: osm_node7106446704, stored in 830_-1632, 830_-1633; containing tile 830_-1632 stores it (#542)$t$),
  ($t$Goethe and Schiller$t$, 41.5264075::double precision, -81.6258631::double precision, $t$One of four copies of Rietschel's Weimar original commissioned by German-Americans, cast by the Lauchhammer foundry, this monument was first dedicated in Wade Park on 9 June 1907 before 65,000 people.$t$, $t$https://en.wikipedia.org/wiki/Goethe_and_Schiller_Monument$t$, $t$#459 hidden-pin row: osm_node9122688224, stored in 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$Father Jahn$t$, 41.5265876::double precision, -81.6257498::double precision, $t$This bust of Friedrich Jahn, one of the founders of modern gymnastics, was dedicated on May 1, 1931.$t$, $t$https://clevelandhistorical.org/index.php/items/show/130$t$, $t$#459 hidden-pin row: osm_node9122653966, stored in 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$Jonas Basanavicius$t$, 41.5271841::double precision, -81.6266537::double precision, $t$The Lithuanian Cultural Garden was dedicated on October 11, 1936 with the unveiling of this bust of Dr. Jonas Basanavicius, a copy of an original by Lithuanian sculptor Jonas Zikaras.$t$, $t$https://clevelandhistorical.org/items/show/133$t$, $t$#459 hidden-pin row: osm_node9115618046, stored in 831_-1632, 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$Vincas Kudirka$t$, 41.5271209::double precision, -81.6262839::double precision, $t$Erected by the Vincas Kudirka Society of Cleveland and dedicated on September 21, 1938, this bronze bust honors the poet, physician and composer of the Lithuanian National Anthem.$t$, $t$https://clevelandhistorical.org/items/show/133$t$, $t$#459 hidden-pin row: osm_node9115664570, stored in 831_-1632, 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$Maironis$t$, 41.5274261::double precision, -81.6264743::double precision, $t$Dedicated in 1961, this bust honors Maciulis Maironis, a priest whose poetry advanced the cause of Lithuanian independence.$t$, $t$https://clevelandhistorical.org/items/show/133$t$, $t$#459 hidden-pin row: osm_node9115664569, stored in 831_-1632, 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$Virgilio$t$, 41.5283487::double precision, -81.626695::double precision, $t$A bust of the poet Virgil opened the Italian Cultural Garden on October 12, 1930, before a crowd of 3000 local Italians celebrating Columbus Day and the 2000th anniversary of Virgil's birth.$t$, $t$https://clevelandhistorical.org/items/show/115$t$, $t$#459 hidden-pin row: osm_node9115618045, stored in 831_-1632, 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$Dante Alighieri$t$, 41.5280013::double precision, -81.6269763::double precision, $t$Dedicated in 2012 in the piazza across from Virgil, this statue honors Dante Alighieri, the father of the modern Italian language and author of the Divine Comedy.$t$, $t$https://www.lagazzettaitaliana.com/photo-exhibit/10741-vita-di-paese-by-joyce-mariani$t$, $t$#459 hidden-pin row: osm_node9115563075, stored in 831_-1632, 831_-1633; containing tile 831_-1633 stores it (#542)$t$),
  ($t$The Thinker$t$, 41.5082984::double precision, -81.6115496::double precision, $t$One of the last casts Rodin supervised personally, this Thinker was blown from its pedestal by a bomb at about 1:00 AM on March 24, 1970, and the museum reinstalled it without repairing the damage.$t$, $t$https://mail.clevelandhistorical.org/items/show/575$t$, $t$#459 hidden-pin row: osm_node4106350897, stored in 830_-1632, 830_-1633; containing tile 830_-1632 stores it (#542)$t$),
  ($t$Steggie$t$, 41.510969::double precision, -81.6129429::double precision, $t$Steggie, an 18-foot-long, 8-foot-tall Stegosaurus sculpture, has greeted museum visitors since 1968; when the original wore out, Louis Paul Jonas Studios cast a new one from the original mold.$t$, $t$https://en.wikipedia.org/wiki/Cleveland_Museum_of_Natural_History$t$, $t$#459 hidden-pin row: osm_node7973678337, stored in 830_-1632, 830_-1633; containing tile 830_-1632 stores it (#542)$t$),
  ($t$Moses Cleaveland$t$, 41.499182::double precision, -81.6932514::double precision, $t$Sculpted by James C. Hamilton and cast in one piece weighing 1,450 lbs., this statue of the city's founder was installed on the Square in a gala ceremony on 22 July 1888.$t$, $t$https://case.edu/ech/articles/m/moses-cleaveland-statue$t$, $t$#459 hidden-pin row: osm_node8591220391, stored in 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$Tom L. Johnson$t$, 41.5001459::double precision, -81.6941129::double precision, $t$Unveiled in 1915, this statue of Cleveland's reform Mayor, Tom L. Johnson, was sculpted by Cleveland School of Art faculty member Herman N. Matzen.$t$, $t$https://www.nps.gov/NR/travel/ohioeriecanal/pub.htm$t$, $t$#459 hidden-pin row: osm_node8405695939, stored in 830_-1633, 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$Free Stamp$t$, 41.5054338::double precision, -81.6924505::double precision, $t$Commissioned by The Standard Oil Company (Ohio) in 1982 for its headquarters on Public Square, Claes Oldenburg and Coosje van Bruggen's giant rubber stamp was donated to the city by BP instead and dedicated here, on its side, on November 15, 1991.$t$, $t$https://en.wikipedia.org/wiki/Willard_Park,_Cleveland$t$, $t$#459 hidden-pin row: osm_node1122411825, stored in 830_-1633, 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$Cleveland Hungarian Heritage Museum$t$, 41.5052033::double precision, -81.6891703::double precision, $t$Operated by the Cleveland Hungarian Heritage Society, this museum preserves the history of Hungarians in northeast Ohio, with Hungarian artwork, folk costumes and other items of Hungarian heritage.$t$, $t$https://en.wikipedia.org/wiki/Cleveland_Hungarian_Museum$t$, $t$#459 hidden-pin row: osm_node368155589, stored in 830_-1633, 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$Polka Hall of Fame$t$, 41.598845::double precision, -81.5263265::double precision, $t$Housed in the historic old city hall of Euclid, renovated in 2000, the National Cleveland-Style Polka Hall of Fame and Museum traces the Cleveland-style polka from its Slovenian roots.$t$, $t$https://en.wikipedia.org/wiki/Polka_Hall_of_Fame$t$, $t$#459 hidden-pin row: osm_way451623186, stored in 832_-1630, 832_-1631; containing tile 832_-1631 stores it (#542)$t$),
  ($t$Euclid v. Ambler Realty Site$t$, 41.5633347::double precision, -81.5418793::double precision, $t$An Ohio Historical Marker dedicated on June 9, 2016 marks the land at the center of Village of Euclid v. Ambler Realty Co., the Supreme Court decision that upheld local zoning; General Motors later built an aircraft plant here during World War II.$t$, $t$https://en.wikipedia.org/wiki/Village_of_Euclid_v._Ambler_Realty_Co.$t$, $t$#459 hidden-pin row: osm_node12239458990, stored in 831_-1630, 831_-1631, 832_-1631; containing tile 831_-1631 stores it (#542)$t$),
  ($t$Mindszenty József Statue$t$, 41.506879::double precision, -81.6892773::double precision, $t$Donated by the Hungarian community of Greater Cleveland in 1977, this monument to Cardinal Mindszenty stands at Cardinal Mindszenty Plaza.$t$, $t$https://en.wikipedia.org/wiki/J%C3%B3zsef_Mindszenty$t$, $t$#459 hidden-pin row: osm_node7106440974, stored in 830_-1633, 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$The St. Mary Church Mural$t$, 41.4903858::double precision, -81.7002833::double precision, $t$Near this spot stood St. Mary's on the Flats, the first Catholic church building in Cleveland, dedicated on June 7, 1840 and torn down in September 1888.$t$, $t$https://en.wikipedia.org/wiki/St._Mary%27s_on_the_Flats$t$, $t$#459 hidden-pin row: osm_node8406182751, stored in 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$Rear Admiral Isaac C. Kidd$t$, 41.5085735::double precision, -81.6940596::double precision, $t$Born in Cleveland in 1884, Rear Admiral Isaac C. Kidd was killed on the bridge of USS Arizona during the attack on Pearl Harbor on December 7, 1941, the first U.S. Navy flag officer killed in action in World War II.$t$, $t$https://en.wikipedia.org/wiki/Isaac_C._Kidd$t$, $t$#459 hidden-pin row: osm_node8591483925, stored in 830_-1634; containing tile 830_-1634 stores it (#542)$t$),
  ($t$Victims of East Ohio Gas Company Explosion$t$, 41.4601822::double precision, -81.5294775::double precision, $t$Sixty-one victims of the East Ohio Gas Co. explosions of Oct. 20, 1944, including 21 never identified, are buried around this monument; the disaster's death toll was 131 people.$t$, $t$https://teachingcleveland.org/?p=734$t$, $t$#459 hidden-pin row: osm_node9121611459, stored in 829_-1630, 829_-1631; containing tile 829_-1631 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
